DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'user_status') THEN
        CREATE TYPE user_status AS ENUM ('active', 'inactive', 'suspended', 'deleted', 'draft');
    END IF;
END
$$ LANGUAGE plpgsql;

CREATE TABLE IF NOT EXISTS users (
    id SERIAL PRIMARY KEY,
    username VARCHAR(150) NOT NULL,
    email VARCHAR(254) NOT NULL, 
    password VARCHAR(255) NOT NULL,
    name VARCHAR(150) NOT NULL,
    country CHAR(2) NOT NULL,
    city VARCHAR(100) NOT NULL,
    legal_address VARCHAR(100) NOT NULL,
    vat_number VARCHAR(30) NOT NULL,
    status user_status NOT NULL DEFAULT 'draft',
    language CHAR(2) NOT NULL,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    deleted_at TIMESTAMPTZ DEFAULT NULL
);

CREATE TABLE IF NOT EXISTS email_verification_tokens (
    id          SERIAL PRIMARY KEY,
    user_id     INT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token       TEXT NOT NULL UNIQUE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    valid_until TIMESTAMPTZ NOT NULL
);


-- Jedinstvena ograničenja (odvojeno da lakše debuguješ konflikte)
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'users_username_uk'
    ) THEN
        ALTER TABLE users ADD CONSTRAINT users_username_uk UNIQUE (username);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'users_email_uk'
    ) THEN
        ALTER TABLE users ADD CONSTRAINT users_email_uk UNIQUE (email);
    END IF;
END
$$ LANGUAGE plpgsql;

-- countries
CREATE TABLE IF NOT EXISTS countries (
    id          SERIAL PRIMARY KEY,
    name        VARCHAR(150) NOT NULL,
    code        CHAR(2)      NOT NULL,
    alpha3_code CHAR(3)      NOT NULL,
    eu_member   BOOLEAN               DEFAULT FALSE,
    continent   VARCHAR(50)           DEFAULT 'Europe'
);


-- Jedinstveni ključevi i indeksi
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'countries_code_uk') THEN
        ALTER TABLE countries ADD CONSTRAINT countries_code_uk UNIQUE (code);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'countries_alpha3_uk') THEN
        ALTER TABLE countries ADD CONSTRAINT countries_alpha3_uk UNIQUE (alpha3_code);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'countries_name_uk') THEN
        ALTER TABLE countries ADD CONSTRAINT countries_name_uk UNIQUE (name);
    END IF;
END
$$ LANGUAGE plpgsql;

CREATE INDEX IF NOT EXISTS idx_countries_code   ON countries(code);
CREATE INDEX IF NOT EXISTS idx_countries_alpha3 ON countries(alpha3_code);

-- cities
CREATE TABLE IF NOT EXISTS cities (
    id         SERIAL PRIMARY KEY,
    name       VARCHAR(150) NOT NULL,
    country_id INT          NOT NULL REFERENCES countries(id) ON DELETE CASCADE,
    latitude   DECIMAL(9, 6),
    longitude  DECIMAL(9, 6)
);

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'cities_name_country_uk') THEN
        ALTER TABLE cities ADD CONSTRAINT cities_name_country_uk UNIQUE (name, country_id);
    END IF;
END
$$ LANGUAGE plpgsql;

CREATE INDEX IF NOT EXISTS idx_cities_country_id ON cities(country_id);

-- Countries (idempotentno)
ON CONFLICT (code) DO NOTHING;

-- Cities (idempotentno)
ON CONFLICT DO NOTHING;

-- enum-i
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'load_type') THEN
    CREATE TYPE load_type AS ENUM ('ftl', 'ltl');
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'truck_type') THEN
    CREATE TYPE truck_type AS ENUM ('refrigerator','curtain','box','flatbed','tanker','container','other');
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'offer_status') THEN
    CREATE TYPE offer_status AS ENUM ('draft','published','expired','cancelled','closed');
  END IF;
END $$;


-- 2025XXXX_add_offer_status_closed.sql () (proveriti d ali treba obzirom da prethodni upit treba da postavi status closed)
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_type t
    JOIN pg_enum e ON t.oid = e.enumtypid
    WHERE t.typname = 'offer_status'
      AND e.enumlabel = 'closed'
  ) THEN
    ALTER TYPE offer_status ADD VALUE 'closed';
  END IF;
END$$;


CREATE TABLE IF NOT EXISTS cargo_offers (
    id SERIAL PRIMARY KEY,

    created_by INT NOT NULL REFERENCES users(id) ON DELETE CASCADE,

    origin_country_id      INT NOT NULL REFERENCES countries(id),
    origin_city_id         INT NOT NULL REFERENCES cities(id),
    destination_country_id INT NOT NULL REFERENCES countries(id),
    destination_city_id    INT NOT NULL REFERENCES cities(id),

    loading_places   INT NOT NULL DEFAULT 1,
    unloading_places INT NOT NULL DEFAULT 1,

    ready_to_load_by    TIMESTAMPTZ NOT NULL,
    delivery_deadline   TIMESTAMPTZ NOT NULL,

    load_type  load_type  NOT NULL,              -- ftl/ltl
    truck_type truck_type NOT NULL,              -- refrigerator/curtain/...

    weight_t   NUMERIC(10,2) NOT NULL,          -- u tonama (npr 24.0)
    volume_m3  NUMERIC(10,2),                    -- opcionalno
    pallets    INT,                              -- broj paleta
    palletized BOOLEAN DEFAULT FALSE,

    temperature_min_c NUMERIC(5,2),             -- za frigo
    temperature_max_c NUMERIC(5,2),

    published_at TIMESTAMPTZ DEFAULT now(),
    expires_at   TIMESTAMPTZ,

    price     NUMERIC(12,2),
    currency  CHAR(3) DEFAULT 'EUR',

    notes TEXT,

    status offer_status NOT NULL DEFAULT 'published',

    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_cargo_offers_origin  ON cargo_offers(origin_country_id, origin_city_id);
CREATE INDEX IF NOT EXISTS idx_cargo_offers_dest    ON cargo_offers(destination_country_id, destination_city_id);
CREATE INDEX IF NOT EXISTS idx_cargo_offers_status  ON cargo_offers(status);
CREATE INDEX IF NOT EXISTS idx_cargo_offers_expires ON cargo_offers(expires_at);

-- enum truck_type i offer_status već postoje i koristiš ih kroz cargo_offers

CREATE TABLE IF NOT EXISTS truck_availability (
    id SERIAL PRIMARY KEY,
    
    created_by INT NOT NULL REFERENCES users(id) ON DELETE CASCADE,

    -- lokacije (odakle je vozilo slobodno → dokle preferira)
    start_country_id INT NOT NULL REFERENCES countries(id),
    start_city_id    INT NOT NULL REFERENCES cities(id),
    end_country_id   INT REFERENCES countries(id),
    end_city_id      INT REFERENCES cities(id),

    -- prozor dostupnosti
    available_from TIMESTAMPTZ NOT NULL,
    available_to   TIMESTAMPTZ NOT NULL,

    -- tip / kapacitet
    truck_type    truck_type NOT NULL,        -- refrigerator/curtain/...
    max_weight_t  NUMERIC(10,2) NOT NULL,     -- u tonama
    max_volume_m3 NUMERIC(10,2),              -- opcionalno m3

    -- način utovara
    full_load    BOOLEAN NOT NULL DEFAULT false,  -- FTL
    partial_load BOOLEAN NOT NULL DEFAULT true,   -- LTL (default true)

    loading_places   INT NOT NULL DEFAULT 1,  -- broj lokacija za utovar
    unloading_places INT NOT NULL DEFAULT 1,  -- broj lokacija za istovar

    -- meta
    published_at TIMESTAMPTZ DEFAULT now(),
    expires_at   TIMESTAMPTZ,

    poster_name TEXT NOT NULL,                -- snapshot imena/username-a
    price_per_km NUMERIC(12,2),
    currency     CHAR(3) DEFAULT 'EUR',

    notes  TEXT,
    status offer_status NOT NULL DEFAULT 'published',

    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_truck_avl_start   ON truck_availability(start_country_id, start_city_id);
CREATE INDEX IF NOT EXISTS idx_truck_avl_end     ON truck_availability(end_country_id, end_city_id);
CREATE INDEX IF NOT EXISTS idx_truck_avl_window  ON truck_availability(available_from, available_to);
CREATE INDEX IF NOT EXISTS idx_truck_avl_status  ON truck_availability(status);